/* eslint-disable */
// 中国地图几何 - projected, simplified, and keyed by the province vocabulary.
//
// WHERE IT COMES FROM. The national boundary set published by Aliyun DataV
// (areas_v3, province level), projected to Albers Equal Area Conic with standard
// parallels 25N/47N on the 105E meridian - the conventional projection for China
// - then simplified with Douglas-Peucker at a 3km tolerance. 569KB of geographic
// JSON becomes 107KB of SVG path data with no visible loss at screen size.
//
// THE KEYS ARE THE VOCABULARY. Every entry is keyed by the same string
// domains/shared/provinces.ts holds and incr/0035's CHECK enforces, so a value
// that reaches this module is guaranteed to find a shape. provinces.test.ts
// proves the three lists agree.
//
// TWO BOUNDING BOXES, not one. The nine-dash line runs to about 4N, so a single
// bbox over everything makes the country a narrow strip in the top half of a very
// tall frame. `viewBox` frames the land; `seaViewBox` frames the South China Sea
// for the corner inset, which is the conventional treatment.
//
// THE Y AXIS IS ALREADY FLIPPED. Albers puts +y at north and SVG grows downward,
// so the projection negates it. Getting this wrong renders a mirrored China that
// still reads as plausible at a glance - it was caught by measuring, not looking.
//
// GENERATED, NOT HAND-EDITED. Regenerate from the source rather than patching a
// path by hand.

export interface ProvinceShape {
  readonly adcode: number;
  /** SVG path data in projected space. */
  readonly d: string;
  /** Label anchor - the province's centroid, projected. */
  readonly cx: number;
  readonly cy: number;
  /** [x, y, w, h] over the province's MAJOR landmasses only. */
  readonly bbox: readonly [number, number, number, number];
}

export interface ChinaGeometry {
  readonly viewBox: readonly [number, number, number, number];
  readonly seaViewBox: readonly [number, number, number, number];
  readonly provinces: Readonly<Record<string, ProvinceShape>>;
  /** The nine-dash line, drawn in the corner inset. */
  readonly sea: string;
}

